static class Program {
 [DllImport("user32.dll")]static extern bool PrintWindow(nint window,nint target,uint flags);
 static void CaptureOwned(Form form,string destination){form.Update();using var bitmap=new Bitmap(form.Width,form.Height);using(var graphics=Graphics.FromImage(bitmap)){var dc=graphics.GetHdc();try{if(!PrintWindow(form.Handle,dc,2))throw new IOException("Owned native PrintWindow failed; no synthetic screenshot substituted.");}finally{graphics.ReleaseHdc(dc);}}bitmap.Save(destination);}
 static string root="",candidate="",output="";static int passed;static readonly List<object> evidence=[];
 static string Hash(string p)=>Convert.ToHexStringLower(SHA256.HashData(File.ReadAllBytes(p)));
 static bool ExactLoadedLibraries(){var checks=new (Type Type,string Path)[]{(typeof(WorkbenchForm),"Jindan.Desktop.dll"),(typeof(RecordDocument),"Jindan.Desktop.Contracts.dll"),(typeof(WorkRecord),"Jindan.Contracts.dll"),(typeof(LocalWorkspace),"Jindan.Infrastructure.dll"),(typeof(Jindan.Core.DomainRules),"Jindan.Core.dll"),(typeof(ModuleCatalog),"Jindan.ModuleHost.dll"),(typeof(UpdateCoordinator),"Jindan.Update.dll")}.Select(x=>new{path=x.Path,loaded=x.Type.Assembly.Location,loadedSha256=Hash(x.Type.Assembly.Location),packagedSha256=Hash(Path.Combine(root,x.Path))}).ToArray();evidence.Add(new{exactLoadedLibraries=checks});return checks.All(x=>x.loadedSha256==x.packagedSha256);}
 static void Check(bool value,string name){if(!value)throw new Exception(name);passed++;Console.WriteLine("PASS "+name);}
 static Dictionary<string,string> Unrelated()=>Directory.GetFiles(root,"*",SearchOption.AllDirectories).Where(f=>!Path.GetRelativePath(root,f).Replace('\\','/').StartsWith("modules/projects/")&&!Path.GetRelativePath(root,f).Replace('\\','/').StartsWith("data/")&&!Path.GetRelativePath(root,f).Replace('\\','/').StartsWith(".updates/")&&!Path.GetRelativePath(root,f).Replace('\\','/').StartsWith("updates/")&&!Path.GetFileName(f).StartsWith("trusted-manifests.json")&&Path.GetFileName(f)!="workspace-location.json"&&!Path.GetFileName(f).EndsWith(".lock")).ToDictionary(f=>Path.GetRelativePath(root,f).Replace('\\','/'),Hash);
 static string Records(){var json=JsonNode.Parse(File.ReadAllText(Path.Combine(root,"data/workspace.json")))!;return json["Records"]!.ToJsonString();}
 static async Task<bool> Health(CancellationToken ct){var start=new ProcessStartInfo(Path.Combine(root,".runtime/dotnet.exe")){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};start.ArgumentList.Add(Path.Combine(root,"Jindan.Desktop.dll"));start.ArgumentList.Add("--healthcheck");start.ArgumentList.Add("--installation-root");start.ArgumentList.Add(root);start.Environment["DOTNET_ROOT"]=Path.Combine(root,".runtime");start.Environment["DOTNET_GENERATE_ASPNET_CERTIFICATE"]="false";using var child=Process.Start(start)!;var stdout=child.StandardOutput.ReadToEndAsync();var stderr=child.StandardError.ReadToEndAsync();try{await child.WaitForExitAsync(ct);}catch{if(!child.HasExited){child.Kill(true);await child.WaitForExitAsync();}throw;}await Task.WhenAll(stdout,stderr);evidence.Add(new{healthPid=child.Id,exit=child.ExitCode,hostSha=Hash(Path.Combine(root,"Jindan.Desktop.dll"))});return child.ExitCode==0;}
 static IEnumerable<Control> Desc(Control c){yield return c;foreach(Control child in c.Controls)foreach(var item in Desc(child))yield return item;}
 static void UiProcess(bool expectedV2,bool seed){var exe=Path.Combine(root,".runtime/dotnet.exe");var info=new ProcessStartInfo(exe){UseShellExecute=false,CreateNoWindow=false,RedirectStandardOutput=true,RedirectStandardError=true};foreach(var a in new[]{typeof(Program).Assembly.Location,"--ui-phase",root,output,expectedV2?"v2":"v1",seed?"seed":"existing"})info.ArgumentList.Add(a);info.Environment["DOTNET_ROOT"]=Path.GetDirectoryName(exe);info.Environment["DOTNET_GENERATE_ASPNET_CERTIFICATE"]="false";using var child=Process.Start(info)!;var stdout=child.StandardOutput.ReadToEndAsync();var stderr=child.StandardError.ReadToEndAsync();using var cancel=new CancellationTokenSource(TimeSpan.FromMinutes(2));try{child.WaitForExitAsync(cancel.Token).GetAwaiter().GetResult();}catch{if(!child.HasExited){child.Kill(true);child.WaitForExit();}throw;}var text=stdout.GetAwaiter().GetResult()+stderr.GetAwaiter().GetResult();Console.Write(text);File.WriteAllText(Path.Combine(output,(expectedV2?"v2":"v1")+(seed?"-initial":"-restored")+"-ui.log"),text);evidence.Add(new{uiPid=child.Id,version=expectedV2?"v2":"v1",seed,exit=child.ExitCode,exactHost=true});Check(child.ExitCode==0,"fresh owned product UI process exited normally");}
 static void Ui(bool expectedV2,bool seed){
  Exception? error=null;using var lease=ApplicationLease.Acquire(root);using var store=new LocalWorkspace(Path.Combine(root,"data"));WorkspaceLocation.Register(root,store.DataRoot);var actor=seed?store.BootstrapAsync("Patch owner","synthetic-patch-66-only",true).GetAwaiter().GetResult():store.LoginAsync("Patch owner","synthetic-patch-66-only").GetAwaiter().GetResult();using var modules=DesktopModules.Load(root);Check(modules.Errors.Count==0&&modules.Entries.Count>=8,"actual complete product modules loaded");using var form=new WorkbenchForm(root,modules,new WorkspaceServices(actor,store,new NoReport()));
  form.Shown+=async(_,_)=>{try{await form.Ready.WaitAsync(TimeSpan.FromSeconds(15));var document=(RecordDocument)form.Documents.Single().Document;await document.Ready.WaitAsync(TimeSpan.FromSeconds(15));if(seed){document.NewRecord();document.SetField("title","진행 프로젝트");document.SetField("status","진행중");await document.SaveAsync();document.NewRecord();document.SetField("title","완료 프로젝트");document.SetField("status","완료");await document.SaveAsync();}await document.RefreshAsync();var bar=Desc(document).OfType<ToolStrip>().Single();var filter=bar.Items.OfType<ToolStripButton>().SingleOrDefault(b=>b.Text=="진행중만 보기");Check((filter is not null)==expectedV2,"actual project filter presence v"+(expectedV2?2:1));var grid=Desc(document).OfType<DataGridView>().Single();Check(grid.Rows.Count==2,"product UI persisted projects");if(filter is not null){filter.PerformClick();Check(grid.Rows.Cast<DataGridViewRow>().Count(r=>r.Visible)==1&&grid.Rows.Cast<DataGridViewRow>().Single(r=>r.Visible).Cells["status"].Value?.ToString()=="진행중","v2 real filter changes visible projects");}CaptureOwned(form,Path.Combine(output,(expectedV2?"v2":"v1")+(seed?"-initial":"-restored")+".png"));try{using var duplicate=ApplicationLease.Acquire(root);throw new Exception("lease accepted");}catch(PackageException ex)when(ex.Code=="APP_RUNNING_OR_UPDATING"){Check(true,"running product app lease blocks updater");}}catch(Exception ex){error=ex;}finally{form.Close();}};
  Application.Run(form);if(error is not null)throw error;
 }
 [STAThread]static int Main(string[] args){ApplicationConfiguration.Initialize();try{if(args.Length==5&&args[0]=="--ui-phase"){root=Path.GetFullPath(args[1]);output=Path.GetFullPath(args[2]);Check(ExactLoadedLibraries(),"fresh child uses exact packaged host");Ui(args[3]=="v2",args[4]=="seed");return 0;}if(args.Length!=3)throw new ArgumentException("install-root candidate output-fresh-directory");root=Path.GetFullPath(args[0]);candidate=Path.GetFullPath(args[1]);output=Path.GetFullPath(args[2]);if(!root.StartsWith(Path.GetFullPath("F:/jindan-dotnet/artifacts/")+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)&&!root.StartsWith(Path.GetFullPath("F:/jindan-dotnet/artifacts/"),StringComparison.OrdinalIgnoreCase))throw new Exception("owned artifact root required");if(Directory.Exists(output)||Directory.Exists(Path.Combine(root,"data")))throw new Exception("fresh synthetic workspace/output required");Directory.CreateDirectory(output);Check(ExactLoadedLibraries(),"harness uses exact packaged product host assembly");var originalProjects=Hash(Path.Combine(root,"modules/projects/Jindan.Modules.Projects.dll"));var unrelated=Unrelated();UiProcess(false,true);var records=Records();var trustPath=Path.Combine(root,"trusted-manifests.json");var trusted=JsonSerializer.Deserialize<string[]>(File.ReadAllText(trustPath))!;var candidateSha=Hash(Path.Combine(candidate,"module.json"));if(!File.Exists(Path.Combine(candidate,"module.json")))throw new Exception("candidate manifest absent");File.WriteAllText(trustPath,JsonSerializer.Serialize(trusted.Append(candidateSha).Distinct().ToArray()));var coordinator=new UpdateCoordinator(new ModuleTrustPolicy(trusted.Append(candidateSha)));coordinator.ApplyAsync(new(root,"projects",candidate,"1.0.0","product-projects-v2"),(_,ct)=>Health(ct)).GetAwaiter().GetResult();Check(Hash(Path.Combine(root,"modules/projects/Jindan.Modules.Projects.dll"))!=originalProjects,"only Projects candidate DLL changed");UiProcess(true,false);Check(Records()==records,"record content unchanged after real patch UI");var after=Unrelated();Check(unrelated.Count==after.Count&&unrelated.All(p=>after.GetValueOrDefault(p.Key)==p.Value),"host and all unrelated module/runtime payload SHA unchanged");coordinator.RollbackLastAsync(root).GetAwaiter().GetResult();Check(Hash(Path.Combine(root,"modules/projects/Jindan.Modules.Projects.dll"))==originalProjects,"rollback restores exact product Projects DLL");UiProcess(false,false);Check(Records()==records,"record content preserved through rollback");try{coordinator.ApplyAsync(new(root,"projects",candidate,"1.0.0","product-projects-health-fail"),(_,ct)=>Task.FromResult(false)).GetAwaiter().GetResult();throw new Exception("health failure accepted");}catch(PackageException){Check(Hash(Path.Combine(root,"modules/projects/Jindan.Modules.Projects.dll"))==originalProjects,"failed product health rolls back exact Projects DLL");}Check(Health(CancellationToken.None).GetAwaiter().GetResult(),"actual product host starts health after failed patch rollback");var final=Unrelated();Check(unrelated.Count==final.Count&&unrelated.All(p=>final.GetValueOrDefault(p.Key)==p.Value),"unrelated product payload remains unchanged after failure rollback");File.WriteAllText(Path.Combine(output,"RESULT.json"),JsonSerializer.Serialize(new{pass=passed,fail=0,root,candidate,originalProjects,unrelated,evidence,reportReady=false,supervisorAccepted=false},new JsonSerializerOptions{WriteIndented=true}));return 0;}catch(Exception e){Console.WriteLine("FAIL "+e);if(Directory.Exists(output))File.WriteAllText(Path.Combine(output,"FAILURE.txt"),e.ToString());return 1;}}
